1	import { EventEmitter } from "node:events";
2	import { Interface, getAddress, Contract, Wallet, isHexString, getBytes } from "ethers";
3	import { getHashiMsgId } from "./hashiHelpers/hashiMsgUtils";
4	import { messageDispatchedAbi, thresholdViewAbi, YaruAbi } from "./hashiHelpers/abi";
5	import { BotEvents } from "./botEvents";
6	import {
7	  HashiExecutionStatus,
8	  HashiMessage,
9	  HashiMessageState,
10	  HashiMessageExecutionVars,
11	  DispatchedTxnData,
12	} from "./hashiHelpers/hashiTypes";
13	import { getHashiBridgeConfig } from "./hashiHelpers/bridgeRoutes";
14	import { getDispatchedMessagesFromEnvio } from "./hashiHelpers/envioQueries";
15	import { getStartBlockNumber, readPendingMessages, updateHashiStateFile } from "./hashiHelpers/stateFile";
16	import { FallbackRpcProvider } from "./fallbackProvider";
17	import { ExecutionError, MissingEnvironmentVariable } from "./errors";
18	
19	const sleep = (ms: number) => new Promise((res) => setTimeout(res, ms));
20	const MAX_BATCH_SIZE = 10;
21	const MAX_BLOCKS_CYCLE = 1_000_000;
22	const MAX_PENDING_TIME_SECONDS = 60 * 60 * 24 * 7; // 1 week
23	const TX_CONFIRM_TIMEOUT_MS = 5 * 60 * 1000;
24	
25	interface HashiExecutorInterface {
26	  sourceChainId: number;
27	  targetChainId: number;
28	  network: string;
29	  emitter: EventEmitter;
30	  fetchBridgeConfig?: typeof getHashiBridgeConfig;
31	  fetchAllMessageLogs?: typeof getDispatchedTxns;
32	  isMessageExecutable?: typeof toExecuteMessage;
33	  executeMsgsOnHashi?: typeof executeBatchOnHashi;
34	  fetchStartBlockNumber?: typeof getStartBlockNumber;
35	  fetchPendingMessages?: typeof readPendingMessages;
36	  updateStateFile?: typeof updateHashiStateFile;
37	}
38	
39	/**
40	 * Run the Hashi executor to process and execute messages.
41	 * @param chainId The chain ID
42	 * @param network The network name
43	 * @param nonce The starting Vea msg nonce
44	 * @param emitter The event emitter
45	 * @param fetchBridgeConfig Function to fetch bridge configuration
46	 * @param fetchVeaInbox Function to fetch Vea Inbox contract instance
47	 * @param isMessageExecutable Function to check if a message is executable
48	 * @param executeMsgsOnHashi Function to execute messages on Hashi
49	 * @returns The updated nonce after processing
50	 */
51	async function runHashiExecutor({
52	  sourceChainId,
53	  targetChainId,
54	  emitter,
55	  fetchBridgeConfig = getHashiBridgeConfig,
56	  fetchAllMessageLogs = getDispatchedTxns,
57	  isMessageExecutable = toExecuteMessage,
58	  executeMsgsOnHashi = executeBatchOnHashi,
59	  fetchStartBlockNumber = getStartBlockNumber,
60	  fetchPendingMessages = readPendingMessages,
61	  updateStateFile = updateHashiStateFile,
62	}: HashiExecutorInterface): Promise<number> {
63	  const bridgeConfig = fetchBridgeConfig(sourceChainId, targetChainId);
64	  const { yaruAddress, yahoAddress, hashiAddress, sourceRPC, targetRPC } = bridgeConfig;
65	  const legacyBlockNumber = await fetchStartBlockNumber(sourceChainId, targetChainId, "hashi", emitter);
66	
67	  if (!yaruAddress || !yahoAddress || !hashiAddress || !sourceRPC || !targetRPC) {
68	    emitter.emit(BotEvents.HASHI_NOT_CONFIGURED, targetChainId);
69	    throw new MissingEnvironmentVariable(`Hashi bridge ${sourceChainId} -> ${targetChainId} (addresses or RPC env)`);
70	  }
71	  const pendingMessages: HashiMessageExecutionVars[] = [];
72	  const localMessages: HashiMessageExecutionVars[] = await fetchPendingMessages(sourceChainId, targetChainId, "hashi");
73	  const executableMessages: HashiMessage[] = [];
74	  const { txns, toBlock } = await fetchAllMessageLogs(
75	    sourceChainId,
76	    targetChainId,
77	    sourceRPC,
78	    yahoAddress,
79	    legacyBlockNumber,
80	    emitter
81	  );
82	  for (const tx of txns) {
83	    // Shared Yahos dispatch for multiple routes; only this route's messages are executable on its Yaru
84	    if (Number(tx.message.targetChainId) !== targetChainId) {
85	      continue;
86	    }
87	    const messageState = await isMessageExecutable({ sourceChainId, hashiMessage: tx.message, emitter });
88	    if (messageState === null) {
89	      continue;
90	    }
91	    if (messageState.executable) {
92	      executableMessages.push(messageState.hashiMessage);
93	    } else if (
94	      messageState.status === HashiExecutionStatus.THRESHOLD_NOT_MET &&
95	      tx.timestamp + MAX_PENDING_TIME_SECONDS >= Math.floor(Date.now() / 1000)
96	    ) {
97	      pendingMessages.push(tx);
98	    }
99	  }
100	  for (const localMsg of localMessages) {
101	    if (Number(localMsg.message.targetChainId) !== targetChainId) {
102	      continue;
103	    }
104	    const messageState = await isMessageExecutable({ sourceChainId, hashiMessage: localMsg.message, emitter });
105	    if (messageState === null) {
106	      continue;
107	    }
108	    if (messageState.executable) {
109	      executableMessages.push(messageState.hashiMessage);
110	    } else if (
111	      messageState.status === HashiExecutionStatus.THRESHOLD_NOT_MET &&
112	      localMsg.timestamp + MAX_PENDING_TIME_SECONDS >= Math.floor(Date.now() / 1000)
113	    ) {
114	      pendingMessages.push(localMsg);
115	    }
116	  }
117	
118	  if (executableMessages.length === 0) {
119	    await updateStateFile(
120	      sourceChainId,
121	      targetChainId,
122	      Math.floor(Date.now() / 1000),
123	      toBlock,
124	      pendingMessages,
125	      "hashi",
126	      emitter
127	    );
128	    return toBlock;
129	  }
130	  emitter.emit(
131	    BotEvents.EXECUTING_HASHI,
132	    executableMessages[0].nonce,
133	    executableMessages[executableMessages.length - 1].nonce
134	  );
135	  await executeMsgsOnHashi(sourceChainId, targetChainId, executableMessages, emitter);
136	  emitter.emit(BotEvents.HASHI_EXECUTED, toBlock);
137	  await updateStateFile(
138	    sourceChainId,
139	    targetChainId,
140	    Math.floor(Date.now() / 1000),
141	    toBlock,
142	    pendingMessages,
143	    "hashi",
144	    emitter
145	  );
146	
147	  return toBlock;
148	}
149	
150	/** * Execute a batch of messages on Hashi (Yaru contract)
151	 * @param chainId The chain ID
152	 * @param params The array of HashiMessageState to execute
153	 * @returns The last nonce processed + 1
154	 */
155	async function executeBatchOnHashi(
156	  sourceChainId: number,
157	  targetChainId: number,
158	  params: HashiMessage[],
159	  emitter: EventEmitter
160	): Promise<void> {
161	  const { yaruAddress, targetRPC } = getHashiBridgeConfig(sourceChainId, targetChainId);
162	  const maxPerTx = 20;
163	  const targetUrls = Array.isArray(targetRPC) ? targetRPC : [targetRPC];
164	  const provider = new FallbackRpcProvider(targetUrls, emitter, targetChainId);
165	  const signer = new Wallet(process.env.PRIVATE_KEY!, provider);
166	  const yaru = new Contract(yaruAddress, YaruAbi, signer);
167	
168	  let cursor = 0;
169	
170	  while (cursor < params.length) {
171	    const chunk = params.slice(cursor, cursor + maxPerTx);
172	
173	    const messages = chunk.map((hashiMessage) => {
174	      const nonce = BigInt(hashiMessage.nonce);
175	      const targetChainId = BigInt(hashiMessage.targetChainId);
176	      const threshold = BigInt(hashiMessage.threshold);
177	
178	      let dataBytes: string | Uint8Array = hashiMessage.data;
179	      if (typeof dataBytes === "string") {
180	        if (dataBytes === "" || dataBytes === "0x") {
181	          dataBytes = new Uint8Array([]);
182	        } else if (!isHexString(dataBytes)) {
183	          dataBytes = getBytes(dataBytes);
184	        }
185	      } else {
186	        // ensure it is a Uint8Array
187	        dataBytes = new Uint8Array(dataBytes);
188	      }
189	
190	      const reporters = Array.isArray(hashiMessage.reporters) ? [...hashiMessage.reporters] : hashiMessage.reporters;
191	
192	      const adapters = Array.isArray(hashiMessage.adapters) ? [...hashiMessage.adapters] : hashiMessage.adapters;
193	
194	      return {
195	        nonce,
196	        targetChainId,
197	        threshold,
198	        sender: hashiMessage.sender,
199	        receiver: hashiMessage.receiver,
200	        data: dataBytes,
201	        reporters,
202	        adapters,
203	      };
204	    });
205	    cursor += chunk.length;
206	    if (messages.length === 0) {
207	      continue;
208	    }
209	
210	    // Check if the filtered messages are executable before sending the transaction
211	    const filteredMessages = [];
212	    for (const message of messages) {
213	      try {
